const data = pm.response.json();

// Get product ID dynamically from request URL
const requestUrl = pm.variables.replaceIn(
    pm.request.url.toString()
);

const match = requestUrl.match(
    /\/products\/(\d+)\/variants\/?(?:\?|$)/
);

const requestedProductId = match
    ? Number(match[1])
    : null;

// Test 1: Status code
pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

// Test 2: Correct product ID
pm.test("Response matches requested product ID", function () {
    pm.expect(requestedProductId).to.not.be.null;
    pm.expect(data.productId).to.eql(requestedProductId);
});

// Test 3: Variants count
pm.test("Variants total matches array length", function () {
    pm.expect(data.variants).to.be.an("array");
    pm.expect(data.total).to.eql(data.variants.length);
});

// Test 4: Variant fields
pm.test("All variants contain valid data", function () {
    pm.expect(data.variants).to.be.an("array");

    data.variants.forEach(function (variant) {
        pm.expect(variant.id).to.be.a("number");
        pm.expect(variant.sku).to.be.a("string").and.not.empty;
        pm.expect(variant.price).to.be.a("number");
        pm.expect(variant.stock_qty).to.be.a("number");
        pm.expect(variant.reserved_qty).to.be.a("number");
        pm.expect(variant.available).to.be.a("number");
    });
});

// Test 5: Inventory consistency
pm.test("Available stock matches inventory", function () {
    data.variants.forEach(function (variant) {
        pm.expect(variant.stock_qty).to.be.at.least(0);
        pm.expect(variant.reserved_qty).to.be.at.least(0);
        pm.expect(variant.available).to.eql(
            variant.stock_qty - variant.reserved_qty
        );
    });
});

