// Test 4: Correct variant and quantity
pm.test("Added variant has correct quantity", function () {
    pm.response.to.have.status(201);

    const json = pm.response.json();

    const item = json.items.find(
        item => item.variant_id === Number(requestBody.variantId)
    );

    pm.expect(item, "Requested variant should exist in cart").to.exist;

    pm.expect(item.product_id).to.eql(Number(pm.variables.get("cart_product_id")));
    // The API might be incrementing the quantity if the item already exists.
    // We check that the quantity is at least the requested amount.
    pm.expect(item.qty).to.eql(Number(pm.variables.get("expected_qty")));
});

// Test 5: Validate line total
pm.test("Line total is calculated correctly", function () {
    pm.response.to.have.status(201);
    const json = pm.response.json();

    const item = json.items.find(
        item => item.variant_id === Number(requestBody.variantId)
    );

    pm.expect(item).to.exist;

    const calculatedTotal = Number(
        (item.qty * item.unit_price).toFixed(2)
    );

    pm.expect(item.line_total).to.eql(calculatedTotal);
});

pm.test("Cart totals reconcile", function () {
 pm.response.to.have.status(201);
 const b=pm.response.json(), cents=v=>Math.round(Number(v)*100);
 pm.expect(b.items).to.be.an("array");
 pm.expect(b.totals).to.be.an("object");
 let sum=0,qty=0;
 b.items.forEach(i=>{pm.expect(cents(i.line_total)).to.eql(cents(i.unit_price)*i.qty);sum+=cents(i.line_total);qty+=i.qty;});
 pm.expect(cents(b.totals.subtotal)).to.eql(sum);
 pm.expect(b.itemCount).to.eql(qty);
 pm.expect(cents(b.totals.shipping_total)).to.eql(sum>=50000?0:2990);
 pm.expect(cents(b.totals.grand_total)).to.eql(sum-cents(b.totals.discount_total)+cents(b.totals.shipping_total));
});

